package com.disasterrelief.controller;
import java.util.Map; import com.disasterrelief.service.ReliefService; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { private final ReliefService s; public DashboardController(ReliefService s){this.s=s;} @GetMapping("/stats") public Map<String,Long> stats(){long capacity=s.totalShelterCapacity(), occupancy=s.currentShelterOccupancy();return Map.of("totalVolunteers",s.volunteerCount(),"availableResources",s.availableResources(),"activeShelters",s.activeShelters(),"pendingRequests",s.pendingRequests(),"assignedRequests",s.assignedRequests(),"inProgressRequests",s.inProgressRequests(),"resolvedRequests",s.resolvedRequests(),"totalShelterCapacity",capacity,"currentShelterOccupancy",occupancy,"availableShelterSpaces",capacity-occupancy);} }
